export function summarizeOrders(orders) {
  const summary = new Map();
  for (const order of orders) {
    if (order.status === 'cancelled') continue;
    const value = order.items.reduce((sum, item) => sum + item.quantity * item.unitPrice, 0);
    const current = summary.get(order.customer) ?? { count: 0, total: 0 };
    current.count += 1;
    current.total += value;
    summary.set(order.customer, current);
  }
  return [...summary.entries()]
    .map(([customer, data]) => ({ customer, count: data.count, total: Number(data.total.toFixed(2)) }))
    .sort((a, b) => a.customer.localeCompare(b.customer));
}
